@@ -55,3 +55,35 @@ export function waste(store, batchId, qty, { at, ref = "" }) {
   batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
   return record(store, { type: "waste", batchId, qty, at, ref });
 }
+
+/** Moves `qty` of a batch to location `to`, splitting it when partial. */
+export function transfer(store, batchId, toOrOpts, maybeQty, { at = "" } = {}) {
+  const { to, qty, at: optsAt } =
+    typeof toOrOpts === "object" && toOrOpts !== null
+      ? toOrOpts
+      : { to: toOrOpts, qty: maybeQty, at };
+  const batch = getBatch(store, batchId);
+  if (!store.data.locations.some((loc) => loc.id === to))
+    throw new AppError("unknown_location", { id: to });
+  if (typeof qty !== "number" || !(qty > 0) || Math.round(qty * 1000) !== qty * 1000 || qty > batch.qty)
+    throw new AppError("invalid_qty");
+  if (qty === batch.qty) {
+    batch.location = to;
+    return batch;
+  }
+  const when = optsAt ?? at;
+  batch.qty = Math.round((batch.qty - qty) * 1000) / 1000;
+  const split = {
+    id: store.nextId("batch"),
+    itemId: batch.itemId,
+    lot: batch.lot,
+    qty,
+    receivedOn: batch.receivedOn,
+    expires: batch.expires,
+    location: to,
+  };
+  store.data.batches.push(split);
+  record(store, { type: "adjust", batchId: batch.id, qty, at: when, ref: `transfer:${split.id}` });
+  record(store, { type: "adjust", batchId: split.id, qty, at: when, ref: `transfer:${batch.id}` });
+  return split;
+}
